def url(path):
    return DOMAIN + path


def shell(path, title, description, content, structured=None):
    data = [{'@context': 'https://schema.org', '@type': 'WebSite', 'name': NAME, 'url': DOMAIN + '/'}]
    if structured:
        data.extend(structured)
    schema = json.dumps(data, ensure_ascii=False).replace('<', '\\u003c')
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{escape(title)} | {NAME}</title><meta name="description" content="{escape(description, quote=True)}">
<link rel="canonical" href="{url(path)}"><meta property="og:type" content="{'article' if path.startswith('/articles/') else 'website'}">
<meta property="og:title" content="{escape(title, quote=True)}"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:url" content="{url(path)}"><meta property="og:site_name" content="{NAME}">
<meta name="twitter:card" content="summary"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css">
<script type="application/ld+json">{schema}</script></head><body>
<a class="skip" href="#main">Skip to content</a>
<header class="header"><a class="brand" href="/" aria-label="Spiritual AI Reviews home"><span class="brand-icon" aria-hidden="true">✳</span><span>Spiritual AI<span class="brand-sub">REVIEWS & FIELD NOTES</span></span></a>
<nav aria-label="Main navigation"><a href="/topics/self-understanding/">Self-understanding</a><a href="/topics/learning/">Learning</a><a href="/topics/business-ai/">Business AI</a><a href="/about/">About</a></nav></header>
<main id="main">{content}</main>
<footer><div><a class="footer-brand" href="/">Spiritual AI Reviews</a><p>Thoughtful tools. Clearer decisions.</p></div><div><p>Published by <a href="https://keshavbruh.in/">Keshav Baliyan</a>.<br>We own the products covered here.</p><a href="/editorial-policy/">Editorial policy</a> · <a href="/privacy/">Privacy</a> · <a href="/about/">Contact</a></div><p class="copyright">© 2026 Spiritual AI Reviews</p></footer>
</body></html>'''


def card(a):
    cat = CATEGORIES[a['category']][0]
    return f'''<article class="card"><div class="card-meta"><span>{cat}</span><span>{a['kind']}</span></div><h3><a href="/articles/{a['slug']}/">{a['title']}</a></h3><p>{a['description']}</p><a class="read-link" href="/articles/{a['slug']}/">Read article <span aria-hidden="true">↗</span><span class="sr-only">: {a['title']}</span></a></article>'''


PAGES = []
def write(path, title, description, content, structured=None):
    target = ROOT / path.strip('/') / 'index.html'
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(shell(path, title, description, content, structured))
    PAGES.append(path)


