        label = CATEGORIES[a['category']][0]
        content = f'''<article class="article"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a> / <a href="/topics/{a['category']}/">{label}</a></nav><header class="article-header"><p class="eyebrow">{a['kind'].upper()}</p><h1>{a['title']}</h1><p class="lead">{a['intro']}</p><p class="byline">By <a href="/about/">Keshav Baliyan</a> · Published <time datetime="{DATE}">October 3, 2026</time></p></header><aside class="article-disclosure"><strong>Ownership disclosure</strong><p>The author owns Spiritual AI, 21 Days, and AI Helper. Product descriptions are based on public pages checked on October 3, 2026. This is not an independent benchmark or a verified customer review.</p></aside><nav class="toc" aria-label="On this page"><strong>On this page</strong><ol>'''
